cards.extra_styles:
.clock-face { height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:clamp(10px,2cqh,30px); }
.clock-time { font-size:clamp(48px,min(25cqw,42cqh),480px); font-weight:250; letter-spacing:-.055em; line-height:1.05; font-variant-numeric:tabular-nums; white-space:nowrap; }
.clock-date { color:#a5b9cf; font-size:clamp(17px,min(2.5cqw,4cqh),48px); font-weight:400; letter-spacing:.015em; }
.clock-kicker { display:flex; align-items:center; gap:12px; color:#a5b9cf; font-size:clamp(12px,1.1cqw,22px); letter-spacing:.2em; font-weight:500; }
.clock-dot { width:7px; height:7px; border-radius:50%; background:#8fdbed; box-shadow:0 0 18px #8fdbed55; }
.clock-weather { display:flex; align-items:center; gap:clamp(14px,2cqw,38px); text-align:left; min-width:0; }
.clock-weather ha-icon { color:#8fdbed; --mdc-icon-size:clamp(38px,min(5cqw,9cqh),90px); flex-shrink:0; }
.clock-current { flex:1; min-width:0; }
.clock-temp { color:#f1f5f9; font-size:clamp(25px,min(3.6cqw,6.5cqh),66px); line-height:1.15; font-weight:350; }
.clock-condition { color:#a5b9cf; font-size:clamp(12px,min(1.3cqw,2.5cqh),26px); margin-top:5px; white-space:normal; }
.clock-metric { min-width:clamp(60px,9cqw,180px); padding-left:clamp(14px,2.8cqw,50px); border-left:1px solid #ffffff15; }
.clock-metric-label { color:#a5b9cf; font-size:clamp(10px,1cqw,19px); margin-bottom:7px; }
.clock-metric-value { color:#e2edf5; font-size:clamp(16px,1.8cqw,34px); font-weight:400; }
.clock-link { color:#8fdbed; font-size:clamp(16px,2cqw,32px); padding-left:10px; }
@container (max-width:600px) { .clock-weather { flex-wrap:wrap; gap:16px; } .clock-metric { flex:1; border:0; padding:14px 0 0; border-top:1px solid #ffffff15; } .clock-metric-label { font-size:12px; } .clock-metric-value { font-size:20px; } .clock-current { flex-basis:60%; } .clock-link { display:none; } .clock-date { font-size:clamp(16px,4cqw,24px); } .clock-time { font-size:32cqw; } }

custom_fields.face:
[[[
const isNight = states[variables.var_assistsat_entity]?.attributes?.mode === 'night';
return `<div class="clock-face"><div class="clock-time" style="color:${isNight ? '#a52b2b' : '#f1f5f9'}">${variables.var_current_time}</div>${isNight ? '' : '<div class="clock-date">' + variables.var_date_long + '</div>'}</div>`;
]]]

